describe("collisions", () => {
  // A one-tile shoal wall at column 10 and a land block to the south.
  const walledRows = [
    "..........%.........",
    "..........%.........",
    "..........%.........",
    "..........%.........",
    "..........%.........",
    "..........%.........",
    "....................",
    "....................",
    "######..............",
    "######..............",
  ];
  const walled = testConfig(walledRows);

  it("stops a ship at full speed flush against a shoal, without passing through", () => {
    const trail = sailFor(shipAt(2, 3, 0, walled), FULL_AHEAD, 200, walled);
    const last = trail.at(-1)!;
    expect(last.x).toBe(10 * tile - 1 - config.ship.hullHalfSize);
    expect(last.speed).toBe(0);
    for (const ship of trail) {
      expect(toTilePosition(walled, ship.x + config.ship.hullHalfSize, ship.y).tileX).toBeLessThan(10);
      expect(hullIsClear(walled, ship.x, ship.y)).toBe(true);
    }
  });

  it("never tunnels, even at a speed of several tiles per step", () => {
    // A shoal wall across the whole sea at column 10, and a ship five tiles a step.
    const fast = testConfig(Array.from({ length: 12 }, () => "..........%........."), { maxSpeed: 5 * tile, acceleration: 5 * tile });
    for (const heading of [0, 4, 8, 60, 56]) {
      const trail = sailFor(shipAt(2, 6, heading, fast), FULL_AHEAD, 50, fast);
      expect(trail[0]!.speed).toBe(5 * tile);
      for (const ship of trail) {
        expect(ship.x + fast.ship.hullHalfSize).toBeLessThan(10 * tile);
        expect(hullIsClear(fast, ship.x, ship.y)).toBe(true);
      }
    }
    // Heading west from beyond the wall, it stops against the wall's east face.
    const back = sailFor(shipAt(18, 6, 32, fast), FULL_AHEAD, 5, fast).at(-1)!;
    expect(back.x).toBe(11 * tile + fast.ship.hullHalfSize);
    expect(back.speed).toBe(0);
  });

  it("slides along an obstacle it meets at an angle, and runs aground head-on", () => {
    // South-east into the land block's north face: blocked on y, it keeps sailing east along it.
    const trail = sailFor(shipAt(0, 5, 8, walled), FULL_AHEAD, 60, walled);
    const againstLand = trail.filter((ship) => ship.y === 8 * tile - 1 - config.ship.hullHalfSize);
    expect(againstLand.length).toBeGreaterThan(2);
    expect(againstLand.at(-1)!.x).toBeGreaterThan(againstLand[0]!.x);
    expect(againstLand.at(-1)!.speed).toBeGreaterThan(0);
    // Due south into the same face: it stops.
    const headOn = sailFor(shipAt(2, 5, 16, walled), FULL_AHEAD, 60, walled).at(-1)!;
    expect(headOn.y).toBe(8 * tile - 1 - config.ship.hullHalfSize);
    expect(headOn.speed).toBe(0);
  });

  it("keeps the hull off land and shoals on the real map under random helm, from every spawn slot and each dock", () => {
    const starts = [
      ...config.spawnSlots.map((slot) => shipAt(slot.tileX, slot.tileY, compassHeading(slot.facing))),
      ...config.map.docks.map((dock) => shipAt(dock.tileX, dock.tileY, 0)),
    ];
    let rng = 20260924;
    let collisions = 0;
    for (const start of starts) {
      let ship = start;
      let input = FULL_AHEAD;
      for (let index = 0; index < 1500; index++) {
        if (index % 15 === 0) {
          const drawn = nextRandom(rng);
          rng = drawn.state;
          // Mostly full ahead, turning either way or holding course.
          input = helm((drawn.value % 3) - 1, drawn.value % 7 === 0 ? -1 : 1);
        }
        const next = sail(config, ship, input);
        if (next.speed === 0 && ship.speed > 0) collisions++;
        const { tileX, tileY } = toTilePosition(config, next.x, next.y);
        expect(isNavigable(config.map, tileX, tileY)).toBe(true);
        expect(hullIsClear(config, next.x, next.y)).toBe(true);
        ship = next;
      }
    }
    // The walk really did meet obstacles.
    expect(collisions).toBeGreaterThan(0);
  });
});

describe("docking", () => {
  const harbour = testConfig([
    "..........",
    "..........",
    "...####...",
    "...##D....",
    "..........",
    "..........",
  ]);
  const dock = harbour.map.docks[0]!;
  const berth = tileCentre(harbour, dock.tileX, dock.tileY);
  const nearby = { ...shipAt(5, 5, 0, harbour), y: berth.y + tile, x: berth.x + 40 };

  it("moors a slow ship near a dock with interact: it stops at the dock and records it", () => {
    const moored = sail(harbour, { ...nearby, speed: harbour.ship.dockMaxSpeed }, INTERACT);
    expect(moored).toMatchObject({ x: berth.x, y: berth.y, speed: 0, dock: dock.id });
    // It stays moored without throttle, turning or not, interact held or not.
    for (const input of [INTERACT, helm(0, 0), helm(1, 0)]) {
      expect(sailFor(moored, input, 20, harbour).at(-1)).toEqual(moored);
    }
  });

  it("docks at any speed, but not too far or without interact", () => {
    expect(sail(harbour, { ...nearby, speed: harbour.ship.maxSpeed }, INTERACT)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, speed: -harbour.ship.maxReverseSpeed }, INTERACT)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, y: berth.y + 2 * tile }, INTERACT).dock).toBe(NOT_DOCKED);
    expect(sail(harbour, nearby, helm(0, 0)).dock).toBe(NOT_DOCKED);
    expect(sail(harbour, nearby, FULL_AHEAD).dock).toBe(NOT_DOCKED);
  });

  it("docks with the throttle held, ahead or astern, at any speed", () => {
    expect(sail(harbour, nearby, helm(0, -1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, nearby, helm(0, 1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
    expect(sail(harbour, { ...nearby, speed: harbour.ship.maxSpeed }, helm(0, 1, INTERACT_BUTTON))).toMatchObject({ ...berth, speed: 0, dock: dock.id });
  });

  it("docks a ship driven at its dock with ahead held as soon as it is within reach, still at full speed", () => {
    // Heading north (48) from three tiles south of the dock at full speed, full ahead and interact held throughout, as
    // a player drives in: it moors on the first step it starts within the dock's reach, without slowing down first.
    const approach = { ...shipAt(dock.tileX, dock.tileY + 3, 48, harbour), speed: harbour.ship.maxSpeed };
    const course = sailFor(approach, helm(0, 1, INTERACT_BUTTON), 40, harbour);
    const moored = course.findIndex((ship) => ship.dock !== NOT_DOCKED);
    expect(course[moored - 1]!.speed).toBe(harbour.ship.maxSpeed);
    expect(dockInReach(harbour, course[moored - 2]!.x, course[moored - 2]!.y)).toBeUndefined();
    expect(dockInReach(harbour, course[moored - 1]!.x, course[moored - 1]!.y)).toBe(dock);
    expect(course.at(-1)).toMatchObject({ ...berth, speed: 0, dock: dock.id });
  });

  it("does not moor across a corner of land the hull could not sail past", () => {
    // South-west of the dock, diagonally: within the dock radius, but the straight run to the berth crosses the corner
    // of the land tile west of the dock.
    const diagonal = shipAt(dock.tileX - 1, dock.tileY + 1, 0, harbour);
    expect((berth.x - diagonal.x) ** 2 + (berth.y - diagonal.y) ** 2).toBeLessThanOrEqual(harbour.ship.dockRadius ** 2);
    expect(hullIsClear(harbour, diagonal.x, diagonal.y)).toBe(true);
    expect(terrainAt(harbour.map, dock.tileX - 1, dock.tileY)).toBe(Terrain.Land);
    expect(hullPathIsClear(harbour, diagonal.x, diagonal.y, berth.x, berth.y)).toBe(false);
    expect(sail(harbour, diagonal, INTERACT)).toEqual(diagonal);
    // Straight up from the tile south of the dock the run is clear, and it moors.
    const below = shipAt(dock.tileX, dock.tileY + 1, 0, harbour);
    expect(hullPathIsClear(harbour, below.x, below.y, berth.x, berth.y)).toBe(true);
    expect(sail(harbour, below, INTERACT)).toMatchObject({ ...berth, dock: dock.id });
    // The check follows the whole segment, not just its ends: both ends clear, a shoal between them.
    const shoaled = testConfig(["..........", "..........", "....%.....", ".........."]);
    expect(hullIsClear(shoaled, 3 * tile + tile / 2, 2 * tile + tile / 2)).toBe(true);
    expect(hullPathIsClear(shoaled, 3 * tile + tile / 2, 2 * tile + tile / 2, 5 * tile + tile / 2, 2 * tile + tile / 2)).toBe(false);
    expect(hullPathIsClear(shoaled, 3 * tile + tile / 2, 1 * tile + tile / 2, 5 * tile + tile / 2, 1 * tile + tile / 2)).toBe(true);
  });

  it("casts off on any throttle without interact and sails in the same step", () => {
    const moored = sail(harbour, nearby, INTERACT);
    const ahead = sail(harbour, { ...moored, heading: 0 }, FULL_AHEAD);
    expect(ahead.dock).toBe(NOT_DOCKED);
    expect(ahead.speed).toBe(harbour.ship.acceleration);
    const astern = sail(harbour, moored, helm(0, -1));
    expect(astern.dock).toBe(NOT_DOCKED);
    expect(astern.speed).toBe(-harbour.ship.reverseAcceleration);
  });

  it("stays moored while interact or the throttle it moored with is held; that throttle casts off only after release", () => {
    // Driven in with ahead held: interact released, ahead still held, the ship stays moored.
    const moored = sail(harbour, nearby, helm(0, 1, INTERACT_BUTTON));
    expect(moored.mooredThrottle).toBe(1);
    expect(sailFor(moored, helm(0, 1, INTERACT_BUTTON), 20, harbour).at(-1)).toEqual(moored);
    expect(sailFor(moored, FULL_AHEAD, 20, harbour).at(-1)).toEqual(moored);
    // Astern is a fresh throttle: it casts off at once.
    expect(sail(harbour, moored, helm(0, -1)).dock).toBe(NOT_DOCKED);
    // Releasing ahead, then pressing it again, casts off.
    const released = sail(harbour, moored, helm(0, 0));
    expect(released).toMatchObject({ dock: dock.id, mooredThrottle: 0 });
    expect(sail(harbour, released, FULL_AHEAD)).toMatchObject({ dock: NOT_DOCKED, mooredThrottle: 0 });
  });

  it("keeps a moored ship's throttle latch when its input entry is missing, as the server leaves it after a lapse", () => {
    const realDock = config.map.docks[0]!;
    const moored = sail(config, shipAt(realDock.tileX, realDock.tileY, 0), helm(0, 1, INTERACT_BUTTON));
    expect(moored).toMatchObject({ dock: realDock.id, mooredThrottle: 1 });
    const stalled = run({ ...createMatchState(1), ships: [moored] }, [], 10 * WORLD_STEP_INTERVAL);
    expect(stalled.ships[0]).toEqual(moored);
    // Unchanged ahead held on resuming does not cast off; neutral input releases the latch, and ahead then casts off.
    const resumed = run(stalled, [{ frame: stalled.frame + 1, shipId: moored.id, input: FULL_AHEAD }], 10 * WORLD_STEP_INTERVAL);
    expect(resumed.ships[0]).toEqual(moored);
    const neutral = run(stalled, [{ frame: stalled.frame + 1, shipId: moored.id, input: helm(0, 0) }], WORLD_STEP_INTERVAL);
    expect(neutral.ships[0]).toMatchObject({ dock: realDock.id, mooredThrottle: 0 });
    // A ship at sea with no entry still sails as neutral: it coasts.
    const slot = config.spawnSlots[0]!;
    const underWay = run({ ...createMatchState(1), ships: [{ ...shipAt(slot.tileX, slot.tileY, compassHeading(slot.facing)), speed: 10 }] }, [], WORLD_STEP_INTERVAL);
    expect(underWay.ships[0]!.speed).toBe(10 - config.ship.drag);
  });

  it("moors from any lateral offset when driven into the corner of the shore beside a dock, tilted toward the land", () => {
    // A south dock with land beside it to the west in its row, open sea to the east, and the coast running on east of it
    // one row further north: an inside corner of the shore.
    const map = config.map;
    const corner = map.docks.find(
      (each) => each.side === "S" && terrainAt(map, each.tileX - 1, each.tileY) === Terrain.Land && terrainAt(map, each.tileX + 1, each.tileY) === Terrain.Sea,
    )!;
    const berth = tileCentre(config, corner.tileX, corner.tileY);
    for (let column = corner.tileX; column <= corner.tileX + 4; column++) expect(terrainAt(map, column, corner.tileY - 1)).toBe(Terrain.Land);
    for (let row = corner.tileY; row <= corner.tileY + 3; row++) {
      for (let column = corner.tileX + 1; column <= corner.tileX + 3; column++) expect(terrainAt(map, column, row)).toBe(Terrain.Sea);
    }
    // The approach the browser test sails: from 1–3 tiles east and 2–4 tiles south of the dock, at a heading one or two
    // units west of north, ahead and interact held together from a slow start. Every lateral offset across those tiles,
    // 16 sub-units apart, moors on the first step it starts within the dock's reach with a clear run to the berth,
    // never touching the shore.
    const north = compassHeading("N");
    let approaches = 0;
    for (const heading of [north - 1, north - 2]) {
      for (let x = (corner.tileX + 1) * tile; x < (corner.tileX + 4) * tile; x += 16) {
        for (const [rowsOut, speed] of [[2, config.ship.dockMaxSpeed], [3, 0], [3, config.ship.dockMaxSpeed], [4, 0]] as const) {
          const start = { ...shipAt(corner.tileX + 2, corner.tileY + rowsOut, heading), x, speed };
          const course = sailFor(start, helm(0, 1, INTERACT_BUTTON), 30 * WORLD_STEPS_PER_SECOND);
          const moored = course.findIndex((ship) => ship.dock !== NOT_DOCKED);
          expect(moored, `heading ${heading}, x ${x}, speed ${speed}`).toBeGreaterThan(0);
          expect(course[moored]).toMatchObject({ ...berth, speed: 0, dock: corner.id, mooredThrottle: 1 });
          const before = [start, ...course.slice(0, moored)];
          expect(dockInReach(config, before.at(-1)!.x, before.at(-1)!.y)).toBe(corner);
          for (const ship of before.slice(0, -1)) expect(dockInReach(config, ship.x, ship.y)).toBeUndefined();
          for (const ship of before.slice(1)) expect(ship.speed).toBeGreaterThan(0);
          for (const ship of course) expect(hullIsClear(config, ship.x, ship.y)).toBe(true);
          approaches++;
        }
      }
    }
    expect(approaches).toBe(2 * 3 * (tile / 16) * 4);
  });

  it("moors from any approach into the berth's open sides, at any speed, on the first step within reach", () => {
    // A dock on the corner of an island, as the slice sea's docks are: land to its west and north, open sea to its east
    // and south, with room to run up to it.
    const island = testConfig([
      "................",
      "................",
      "................",
      "................",
      "....######......",
      "....######......",
      "....######......",
      "....#####D......",
      "................",
      "................",
      "................",
      "................",
      "................",
      "................",
    ]);
    const berthDock = island.map.docks[0]!;
    const centre = tileCentre(island, berthDock.tileX, berthDock.tileY);
    const reach = island.ship.dockRadius;
    const outward = { E: { dx: 1, dy: 0 }, S: { dx: 0, dy: 1 }, W: { dx: -1, dy: 0 }, N: { dx: 0, dy: -1 } } as const;
    const divide = (value: number) => divTrunc(value, HEADING_SCALE);
    const openSides = (["E", "S", "W", "N"] as const)
      .map((side) => ({ side, ...outward[side] }))
      .filter(({ dx, dy }) => isNavigable(island.map, berthDock.tileX + dx, berthDock.tileY + dy));
    expect(openSides.map(({ side }) => side)).toEqual(["E", "S"]);
    const headings: number[] = [];
    for (let heading = 0; heading < HEADING_COUNT; heading += 8) {
      // Pointing into an open side: sailing against that side's outward direction.
      if (openSides.some(({ dx, dy }) => dx * HEADING_DX[heading]! + dy * HEADING_DY[heading]! < 0)) headings.push(heading);
    }
    expect(headings).toEqual([24, 32, 40, 48, 56]);
    let approaches = 0;
    for (const heading of headings) {
      const along = { x: HEADING_DX[heading]!, y: HEADING_DY[heading]! };
      for (let offset = 16 - reach; offset < reach; offset += 32) {
        // The lane passes the berth `offset` sub-units to its side. Lanes whose closest point to the berth has no clear
        // run to it pass over the land beside the dock rather than into an open side.
        const closest = { x: centre.x + divide(-along.y * offset), y: centre.y + divide(along.x * offset) };
        if (!hullPathIsClear(island, closest.x, closest.y, centre.x, centre.y)) continue;
        const runUp = reach + 2 * tile;
        for (const speed of [0, divTrunc(island.ship.maxSpeed, 2), island.ship.maxSpeed]) {
          const start = { ...shipAt(0, 0, heading, island), x: closest.x - divide(along.x * runUp), y: closest.y - divide(along.y * runUp), speed };
          expect(hullIsClear(island, start.x, start.y)).toBe(true);
          const course = sailFor(start, helm(0, 1, INTERACT_BUTTON), 100, island);
          const moored = course.findIndex((ship) => ship.dock !== NOT_DOCKED);
          const label = `heading ${heading}, offset ${offset}, speed ${speed}`;
          expect(moored, label).toBeGreaterThanOrEqual(0);
          expect(course[moored], label).toMatchObject({ ...centre, speed: 0, dock: berthDock.id, mooredThrottle: 1 });
          // Every step before it started outside the reach or without a clear run, and none ran aground on the way.
          const before = [start, ...course.slice(0, moored)];
          expect(dockInReach(island, before.at(-1)!.x, before.at(-1)!.y), label).toBe(berthDock);
          for (const ship of before.slice(0, -1)) expect(dockInReach(island, ship.x, ship.y), label).toBeUndefined();
          for (const ship of before.slice(1)) expect(ship.speed, label).toBeGreaterThan(0);
          approaches++;
        }
      }
    }
    // Each heading keeps most of its lanes: the ones it loses run over the island beside the dock.
    expect(approaches).toBeGreaterThanOrEqual(headings.length * 3 * 12);
  });

  it("docks on the real map at every dock", () => {
    for (const each of config.map.docks) {
      const centre = tileCentre(config, each.tileX, each.tileY);
      expect(sail(config, { ...shipAt(each.tileX, each.tileY, 0), x: centre.x + 1, y: centre.y }, INTERACT).dock).toBe(each.id);
      expect(terrainAt(config.map, each.tileX, each.tileY)).toBe(Terrain.Dock);
    }
  });
});

